<?php
use Illuminate\Foundation\Application;use Illuminate\Foundation\Configuration\Middleware;use Illuminate\Foundation\Configuration\Exceptions;use App\Http\Middleware\ApplyTestClock;use Illuminate\Http\Request;use Illuminate\Validation\ValidationException;use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;
return Application::configure(basePath:dirname(__DIR__))->withRouting(api:__DIR__.'/../routes/api.php',commands:__DIR__.'/../routes/console.php',health:'/health')->withMiddleware(function(Middleware $m){$m->append(ApplyTestClock::class);})->withExceptions(function(Exceptions $e){$e->render(function(ValidationException $x,Request $r){if($r->expectsJson())return response()->json(['error'=>$x->getMessage()],400);});$e->render(function(HttpExceptionInterface $x,Request $r){if($r->expectsJson())return response()->json(['error'=>$x->getMessage()?:'Error'], $x->getStatusCode());});})->create();